const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={name:'Aarav Sharma',degree:'B.Tech · Computer Science',year:'3',cgpa:8.2,interest:'Software development',skills:'JavaScript, HTML, CSS, Python, Git',hours:6};
let state;state={profile:{...defaults,...state?.profile},tasks:state?.tasks||[],saved:state?.saved||[],resume:state?.resume||'',answers:state?.answers||{}};
function save(){if(typeof queueBackendSave==='function')queueBackendSave();}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
const roles=[{name:'Frontend Developer',domain:'Software development',skills:['HTML','CSS','JavaScript','React','Git','Testing'],desc:'Build thoughtful, accessible web experiences.',symbol:'</>'},{name:'Data Analyst',domain:'Data & analytics',skills:['Python','SQL','Excel','Statistics','Visualization','Communication'],desc:'Turn data into clear, useful decisions.',symbol:'▥'},{name:'UX Designer',domain:'Design',skills:['Figma','Research','Prototyping','Accessibility','Communication','Testing'],desc:'Create products that put people first.',symbol:'◇'},{name:'Backend Developer',domain:'Software development',skills:['Python','SQL','APIs','Git','Testing','Databases'],desc:'Design reliable systems behind great products.',symbol:'{ }'}];
const skillset=()=>new Set(state.profile.skills.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean));
const matches=()=>roles.map(r=>({...r,known:r.skills.filter(s=>skillset().has(s.toLowerCase())),score:Math.round(r.skills.filter(s=>skillset().has(s.toLowerCase())).length/r.skills.length*100)})).sort((a,b)=>(b.score+(b.domain===state.profile.interest?12:0))-(a.score+(a.domain===state.profile.interest?12:0)));
const target=()=>matches()[0];const gaps=()=>target().skills.filter(s=>!skillset().has(s.toLowerCase()));
const nav=[['dashboard','Overview','M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z'],['profile','My profile','M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0'],['careers','Career explorer','M12 3l9 9-9 9-9-9zM9 15l2-4 4-2-2 4z'],['roadmap','My roadmap','M5 4v16M5 5h13l-3 4 3 4H5'],['courses','Learning hub','M3 4l9 3 9-3v15l-9 3-9-3zM12 7v15'],['jobs','Opportunities','M3 7h18v14H3zM8 7V3h8v4M3 12h18'],['resume','Resume studio','M5 3h10l4 4v14H5zM9 11h6M9 15h6'],['interview','Mock interviews','M3 4h18v13H9l-6 4zM7 8h10M7 12h6'],['government','Government careers','M3 8l9-5 9 5zM5 10v8M12 10v8M19 10v8M3 21h18']];
$('#nav').innerHTML=nav.map(([id,label,path])=>`<a href="#${id}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg>${label}</a>`).join('');
const head=(eyebrow,title,sub)=>`<div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${sub}</p>`;
const row=r=>`<div class="career-row"><div class="career-icon">${esc(r.symbol)}</div><div class="grow"><h3>${r.name}</h3><p>${r.desc}</p></div><div class="match">${r.score}%<small>skill match</small></div></div>`;
function tasks(){return [{id:'profile',title:'Make your profile truly yours',detail:'Add your education, interests and current skills.',page:'profile'},{id:'learn-'+target().name,title:gaps().length?'Build your '+gaps()[0]+' foundation':'Put your skills into a portfolio project',detail:'Start with one focused learning session.',page:'courses'},{id:'interview',title:'Practice your first interview answer',detail:'A small rehearsal makes a big difference.',page:'interview'}]}
function dashboard(){let r=target();return `<div class="title-row"><div>${head('YOUR CAREER, IN MOTION',`Hey ${esc(state.profile.name.split(' ')[0])}, let's move forward.`,`A clearer direction. A stronger skill set. A future that's yours.`)}</div><span class="date">Your personal career workspace</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">FROM CAMPUS TO WHAT’S NEXT</div><h2>Big ambitions.<br>A clear path to get there.</h2><p>Discover where your strengths can take you, and turn your next steps into real progress.</p><button class="lime" data-page="roadmap">Explore my career roadmap <span style="margin-left:18px">↗</span></button></div><div class="orbit" aria-hidden="true"><span class="spark">✦</span></div></section><div class="stats"><div class="stat"><div class="stat-label">Top career skill match</div><b>${r.score}<span style="font-size:16px">%</span></b><small>${r.known.length} of ${r.skills.length} core skills listed</small></div><div class="stat"><div class="stat-label">Career paths to explore</div><b>${roles.length.toString().padStart(2,'0')}</b><small>Ranked around your profile</small></div><div class="stat"><div class="stat-label">Skills to work on</div><b>${gaps().length.toString().padStart(2,'0')}</b><small>For ${r.name.toLowerCase()}</small></div><div class="stat"><div class="stat-label">Saved opportunities</div><b>${state.saved.length.toString().padStart(2,'0')}</b><small>Your personal shortlist</small></div></div><div class="grid"><section class="card"><div class="section-title"><h2>Where you could go</h2><a href="#careers">Explore careers ↗</a></div>${matches().slice(0,3).map(row).join('')}<div class="note">Based on the skills and interests in your profile. Your path is yours to choose.</div></section><section class="card"><div class="section-title"><h2>Your skill snapshot</h2><span class="badge">${r.name}</span></div>${r.skills.slice(0,4).map(s=>`<div class="skill-label">${s}<span>${skillset().has(s.toLowerCase())?'Listed in profile':'To explore'}</span></div><div class="bar"><i style="width:${skillset().has(s.toLowerCase())?100:0}%"></i></div>`).join('')}<a class="text-btn" href="#profile">Update your skills →</a></section><section class="card"><div class="section-title"><h2>A little progress this week</h2><span class="badge">${tasks().filter(t=>state.tasks.includes(t.id)).length} / 3 complete</span></div>${tasks().map(t=>`<div class="task ${state.tasks.includes(t.id)?'done':''}"><input type="checkbox" aria-label="Complete: ${esc(t.title)}" data-task="${t.id}" ${state.tasks.includes(t.id)?'checked':''}><div class="grow"><strong>${t.title}</strong><p>${t.detail}</p></div><a href="#${t.page}" aria-label="Open ${esc(t.title)}">↗</a></div>`).join('')}</section><section class="card feature-box"><div class="eyebrow">PRACTICE BUILDS CONFIDENCE</div><h2 style="margin-top:15px">Your next interview?<br>You've got this.</h2><p>Try a guided practice session, reflect on your answer, and get better one question at a time.</p><button class="primary" data-page="interview">Start a practice session ↗</button></section></div>`}
function profile(){let p=state.profile;return head('THE STARTING POINT','Your story starts here.','Your profile powers career matching. Sign in to save your profile and progress to your account.')+`<form id="profile-form" class="card"><div class="form-grid"><div><label for="name">Full name</label><input id="name" name="name" required maxlength="70" value="${esc(p.name)}"></div><div><label for="degree">Degree / academic programme</label><input id="degree" name="degree" required maxlength="100" value="${esc(p.degree)}"></div><div><label for="year">Year of study</label><select id="year" name="year">${['1','2','3','4','Graduate'].map(y=>`<option ${p.year==y?'selected':''}>${y}</option>`).join('')}</select></div><div><label for="cgpa">CGPA (out of 10)</label><input type="number" id="cgpa" name="cgpa" min="0" max="10" step="0.1" required value="${p.cgpa}"></div><div><label for="interest">Area of interest</label><select id="interest" name="interest">${['Software development','Data & analytics','Design'].map(i=>`<option ${p.interest===i?'selected':''}>${i}</option>`).join('')}</select></div><div><label for="hours">Weekly learning hours</label><input type="number" id="hours" name="hours" min="1" max="40" required value="${p.hours}"></div><div class="full"><label for="skills">Current skills (comma separated)</label><textarea id="skills" name="skills" required maxlength="1500">${esc(p.skills)}</textarea><p class="muted">Examples: JavaScript, React, SQL, Python, Git, Communication</p></div></div><button class="primary" type="submit">Save & update recommendations ↗</button></form><div class="note">Academic context: year helps frame your roadmap. CGPA is recorded for your review; it is not used as a proxy for ability or job eligibility. Match scores only measure overlap with this demo's skill checklist.</div><div class="actions"><button id="export" class="outline">Export my data</button><button id="reset" class="outline">Reset demo data</button></div>`}
function careers(){return head('EXPLORE YOUR POSSIBILITIES','Find a direction that fits.','Compare paths, see your strengths, and discover what to learn next.')+`<div class="cards">${matches().map(r=>`<section class="card"><span class="badge">${r.domain}</span><h2>${r.name}</h2><p>${r.desc}</p><div class="big-number">${r.score}%</div><p>${r.known.length} of ${r.skills.length} core skills listed</p><div class="chips">${r.skills.map(s=>`<span class="chip">${skillset().has(s.toLowerCase())?'✓ ':''}${s}</span>`).join('')}</div><button class="primary" data-target="${r.name}">Build this roadmap ↗</button></section>`).join('')}</div><p class="note">Ranking = skill overlap + a small interest preference. Scores are descriptive, not hiring predictions. You can explore any path regardless of score.</p>`}
let chosenRole=null;
function roadmap(){let r=roles.find(r=>r.name===chosenRole)||target();let missing=r.skills.filter(s=>!skillset().has(s.toLowerCase()));let weeks=Math.max(4,Math.ceil((missing.length*12+24)/state.profile.hours));return head('A DIRECTION, NOT A DEADLINE',`Your path to ${r.name}.`,`A flexible ${weeks}-week planning estimate at ${state.profile.hours} hours/week. Adjust the pace as you go.`)+`<div class="grid"><section class="card">${[{title:'Start with your foundations',text:missing.length?'Focus on '+missing.join(', ')+'. Use the learning hub and practice after each lesson.':'Your checklist is covered. Revisit weak areas with short exercises.'},{title:'Build something you can show',text:`Create a ${r.domain==='Design'?'research-backed redesign with a clickable prototype':r.domain==='Data & analytics'?'data analysis with a clear dashboard and written findings':'small deployed application with a README and tests'}. Document decisions and lessons.`},{title:'Tell your story clearly',text:'Turn project work into specific resume bullets. Include your contribution and only outcomes you can verify.'},{title:'Practice, reflect, apply',text:'Rehearse interview answers, request feedback and shortlist suitable opportunities.'}].map((x,i)=>`<div class="step"><div class="step-number">${i+1}</div><div class="grow"><h3>${x.title}</h3><p>${x.text}</p><label><input type="checkbox" data-step="${r.name}-${i}" ${state.tasks.includes(r.name+'-'+i)?'checked':''}> Mark milestone complete</label></div></div>`).join('')}</section><section><div class="card feature-box"><div class="eyebrow">YOUR STARTING POINT</div><h2 style="margin-top:15px">${esc(state.profile.degree)}</h2><p>Year ${esc(state.profile.year)} · CGPA ${state.profile.cgpa}/10</p><p>${missing.length} skills to explore. Plan assumes 12 hours per missing skill plus 24 hours for a project and preparation; it is not a mastery guarantee.</p><button class="primary" data-page="courses">Find learning resources ↗</button></div></section></div>`}
const resources=[['Web foundations','HTML, CSS, JavaScript, Accessibility','MDN Web Docs','https://developer.mozilla.org/en-US/docs/Learn_web_development'],['React foundations','React','React documentation','https://react.dev/learn'],['Python foundations','Python, APIs','Python documentation','https://docs.python.org/3/tutorial/'],['SQL practice','SQL, Databases','SQLBolt','https://sqlbolt.com/'],['Git essentials','Git','Pro Git book','https://git-scm.com/book/en/v2'],['Data learning','Excel, Visualization, Statistics','Microsoft Learn','https://learn.microsoft.com/training/'],['Design foundations','Figma, Research, Prototyping','Figma resource library','https://www.figma.com/resource-library/'],['Testing foundations','Testing','MDN testing guide','https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Testing'],['Communication practice','Communication','OpenLearn','https://www.open.edu/openlearn/']];
function courses(){return head('MAKE ROOM TO GROW','Small lessons. Lasting skills.','A curated learning directory. Check providers for current courses, certificates, costs and availability.')+`<div class="cards">${[...resources].sort((a,b)=>Number(b[1].split(', ').some(s=>gaps().includes(s)))-Number(a[1].split(', ').some(s=>gaps().includes(s)))).map(([name,skills,provider,url])=>`<article class="card"><span class="badge">${skills.split(', ').some(s=>gaps().includes(s))?'Relevant to your skill gaps':'Explore a new skill'}</span><h2>${name}</h2><p>${provider}</p><div class="chips">${skills.split(', ').map(s=>`<span class="chip">${s}</span>`).join('')}</div><a target="_blank" rel="noopener noreferrer" href="${url}">Open learning resource ↗</a></article>`).join('')}</div>`}
const jobs=[{id:1,title:'Frontend Developer Intern',company:'Sample · Studio North',type:'Internship',location:'Remote',skills:['JavaScript','React','Git']},{id:2,title:'Junior Data Analyst',company:'Sample · Insight Labs',type:'Full-time',location:'Bengaluru',skills:['Python','SQL','Excel']},{id:3,title:'Product Design Intern',company:'Sample · Form Studio',type:'Internship',location:'Hybrid',skills:['Figma','Research','Prototyping']},{id:4,title:'Backend Engineering Intern',company:'Sample · BuildWorks',type:'Internship',location:'Remote',skills:['Python','APIs','Git']}];
function jobsPage(){return head('YOUR NEXT OPPORTUNITY','Make your next move.','Sample listings for project demonstration — these are not open vacancies.')+`<div class="filters"><input id="job-search" aria-label="Search opportunities" placeholder="Search by role, skill or location"><select id="job-type" aria-label="Filter opportunity type"><option>All opportunities</option><option>Internship</option><option>Full-time</option><option>Saved</option></select></div><div id="job-list" class="cards"></div>`}
function renderJobs(){let q=$('#job-search').value.toLowerCase(),type=$('#job-type').value;let list=jobs.filter(j=>(JSON.stringify(j).toLowerCase().includes(q))&&(type==='All opportunities'||type===j.type||(type==='Saved'&&state.saved.includes(j.id))));$('#job-list').innerHTML=list.map(j=>`<article class="card"><span class="badge">${j.type} · ${j.location}</span><h2>${j.title}</h2><p>${j.company}</p><p>${j.skills.filter(s=>skillset().has(s.toLowerCase())).length}/${j.skills.length} requested skills in your profile</p><div class="chips">${j.skills.map(s=>`<span class="chip">${s}</span>`).join('')}</div><button class="outline" data-save="${j.id}">${state.saved.includes(j.id)?'✓ Saved · remove':'Save opportunity'}</button></article>`).join('')||'<p class="empty">No matching opportunities. Try another search.</p>'}
function resume(){return head('PUT YOUR STRENGTHS INTO WORDS','A stronger first impression.','Paste resume text for local checklist feedback. This demo does not send your resume to an AI service.')+`<section class="card"><label for="resume-text">Your resume</label><textarea id="resume-text" rows="12" placeholder="Paste your education, skills, projects and experience here…">${esc(state.resume)}</textarea><div class="actions"><button class="primary" id="review-resume">Review my resume ↗</button><button class="outline" id="download-resume">Download resume text</button></div><div id="resume-feedback" class="feedback" aria-live="polite"></div></section>`}
function reviewResume(){let text=$('#resume-text').value.trim();if(text.length<50){$('#resume-feedback').textContent='Add at least 50 characters so the checklist can review your resume.';return}state.resume=text;save();let checks=[[/education|degree|b\.tech|university|college/i,'Include an education section with degree and graduation year.'],[/project/i,'Add a projects section describing what you built and your contribution.'],[/skills|technologies/i,'Add a clear skills section tailored to your chosen role.'],[/built|designed|implemented|analyzed|developed|led|created/i,'Start experience bullets with clear action verbs.'],[/\d+\s*%|\d+\s*(users|hours|records|tests)/i,'Use measurable outcomes when you can verify them; never invent numbers.'],[/[\w.+-]+@[\w.-]+\.[a-z]{2,}/i,'Include a professional contact email.']];let passed=checks.filter(([r])=>r.test(text)).length;$('#resume-feedback').innerHTML=`<div class="note">${passed}/${checks.length} checklist signals found. This is not an ATS score or hiring prediction.</div><ul>${checks.filter(([r])=>!r.test(text)).map(([,tip])=>`<li>${tip}</li>`).join('')||'<li>Your resume includes all six signals. Check clarity, relevance and factual accuracy next.</li>'}</ul><h3>A useful bullet structure</h3><p>“Built [specific feature] using [tools] to [purpose]; measured [verified outcome].”</p><p class="muted">For ${target().name}, highlight truthful experience with ${target().skills.slice(0,3).join(', ')}.</p>`}
const questions=['Tell me about a project you are proud of. What did you personally contribute?','Describe a difficult problem you solved. How did you decide what to try?','Tell me about a time you worked with a team and handled disagreement.','How would you learn an unfamiliar tool for an upcoming project?'];let qi=0;
function interview(){return head('A SAFE PLACE TO PRACTICE','Confidence comes with practice.','Four guided questions with local structure feedback. No recording, voice analysis or live AI.')+`<section class="card"><div class="section-title"><span class="badge">Question ${qi+1} of ${questions.length}</span><span class="muted">${target().name} preparation</span></div><h2>${questions[qi]}</h2><p class="sub">Try the STAR structure: Situation → Task → Action → Result.</p><label for="answer">Your answer</label><textarea id="answer" rows="8" placeholder="Set the scene, explain your responsibility, then describe your actions and what happened.">${esc(state.answers[qi]||'')}</textarea><div class="actions"><button class="primary" id="feedback-answer">Get practice feedback</button><button class="outline" id="next-question">${qi===3?'Back to first question':'Next question'} →</button></div><div id="interview-feedback" class="feedback" aria-live="polite"></div></section>`}
function government(){return head('EXPLORE PUBLIC SERVICE','A different path. A shared purpose.','Official discovery portals for India. Check each notice for current dates and eligibility; no live openings are asserted here.')+`<div class="cards">${[['National Career Service','Explore employment services and opportunities across sectors.','https://www.ncs.gov.in/'],['UPSC','Read official examination notices, syllabi and eligibility conditions.','https://upsc.gov.in/'],['Staff Selection Commission','Review recruitment notices and examination information.','https://ssc.gov.in/'],['Apprenticeship India','Explore apprenticeship pathways and read provider requirements.','https://www.apprenticeshipindia.gov.in/']].map(([name,desc,url])=>`<article class="card"><span class="badge">Official portal</span><h2>${name}</h2><p>${desc}</p><a href="${url}" target="_blank" rel="noopener noreferrer">Visit official website ↗</a></article>`).join('')}</div><p class="note">Your degree, age, citizenship and other notice-specific conditions may affect eligibility. This prototype does not determine eligibility.</p>`}
function download(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function render(){let page=location.hash.slice(1)||'home';if(page!=='home'&&!nav.some(n=>n[0]===page))page='home';window.careerRevealObserver?.disconnect();document.body.classList.toggle('home-view',page==='home');if(page==='home'){$('#main').innerHTML=landing()+landingSections();initLandingMotion();return;}document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+page);if(a.hash==='#'+page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#breadcrumb').innerHTML='Workspace <span>/</span> '+nav.find(n=>n[0]===page)[1];$('#sidebar-name').textContent=state.profile.name;$('#avatar').textContent=state.profile.name.split(' ').map(w=>w[0]).slice(0,2).join('');$('#main').innerHTML=({dashboard,profile,careers,roadmap,courses,jobs:jobsPage,resume,interview,government}[page])();if(page==='jobs'){renderJobs();$('#job-search').oninput=renderJobs;$('#job-type').onchange=renderJobs}if(page==='profile')$('#profile-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(!d.name.trim()||!d.skills.trim()||!d.degree.trim()){toast('Please add your name, programme and at least one skill.');return}state.profile={...d,name:d.name.trim(),cgpa:Number(d.cgpa),hours:Number(d.hours)};chosenRole=null;save();toast(typeof backendUser!=='undefined'&&backendUser?'Profile updated. Saving to your account…':'Recommendations updated. Sign in to save your progress.');location.hash='dashboard'};}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.page)location.hash=b.dataset.page;if(b.dataset.scroll){document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});let menu=$('#landing-menu');if(menu)menu.hidden=true;$('#landing-menu-toggle')?.setAttribute('aria-expanded','false');}if(b.id==='landing-menu-toggle'){let menu=$('#landing-menu');menu.hidden=!menu.hidden;b.setAttribute('aria-expanded',String(!menu.hidden));}if(b.id==='save-pace'){let hours=Number($('#landing-hours').value);if(!Number.isInteger(hours)||hours<1||hours>40){toast('Choose 1 to 40 whole hours per week.');return}state.profile.hours=hours;save();toast('Weekly learning goal saved.');}if(b.id==='cancel-pace')$('#landing-hours').value=state.profile.hours;if(b.dataset.previewTab){document.querySelectorAll('[data-preview-tab]').forEach(x=>x.classList.toggle('active',x===b));let progress=b.dataset.previewTab==='milestones';$('#preview-gauge').innerHTML=gauge(progress?Math.round(tasks().filter(t=>state.tasks.includes(t.id)).length/3*100):target().score);$('#preview-gauge-title').textContent=progress?'Weekly checklist completed':'Core skills already in your profile';}if(b.dataset.target){chosenRole=b.dataset.target;location.hash='roadmap'}if(b.dataset.save){let id=Number(b.dataset.save);state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();renderJobs()}if(b.id==='review-resume')reviewResume();if(b.id==='download-resume'){let t=$('#resume-text').value.trim();if(!t){toast('Add resume text first.');return}state.resume=t;save();download('my-resume.txt',t)}if(b.id==='export')download('careerbridge-data.json',JSON.stringify(state,null,2));if(b.id==='reset'&&confirm('Reset your profile, answers and saved progress to sample data?')){state={profile:{...defaults},tasks:[],saved:[],resume:'',answers:{}};chosenRole=null;save();render();toast('Demo data reset.')}if(b.id==='next-question'){state.answers[qi]=$('#answer').value;save();qi=(qi+1)%questions.length;render()}if(b.id==='feedback-answer'){let t=$('#answer').value.trim();state.answers[qi]=t;save();let count=t.split(/\s+/).filter(Boolean).length;$('#interview-feedback').innerHTML=count<20?'<p>Add at least 20 words to get useful structure feedback.</p>':`<div class="note">${count} words · Structure checklist, not a hiring assessment.</div><ul><li>${/project|team|during|when|situation/i.test(t)?'You included context. Make sure your responsibility is clear.':'Start with a specific situation or project.'}</li><li>${/implemented|built|created|analyzed|designed|tested|decided/i.test(t)?'An action is visible. Explain why you chose that approach.':'Describe the concrete actions you personally took.'}</li><li>${/result|learned|improved|reduced|delivered|achieved/i.test(t)?'You included an outcome or reflection. Support it with a truthful example.':'Finish with the outcome and what you learned.'}</li><li>${count>220?'Try a more concise version with one main example.':'Practice saying this aloud at a comfortable pace.'}</li></ul>`}});
document.addEventListener('change',e=>{let id=e.target.dataset.task||e.target.dataset.step;if(id){state.tasks=e.target.checked?[...new Set([...state.tasks,id])]:state.tasks.filter(t=>t!==id);save();if(e.target.dataset.task)render()}});
document.addEventListener('input',e=>{if(e.target.id==='answer'){state.answers[qi]=e.target.value;save()}if(e.target.id==='resume-text'){state.resume=e.target.value;save()}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
function gauge(value,color='#ef4d23'){return `<svg class="gauge" viewBox="0 0 200 120" role="img" aria-label="${value} percent"><g>${Array.from({length:40},(_,i)=>{let a=Math.PI+i*Math.PI/39;return `<line x1="${100+70*Math.cos(a)}" y1="${100+70*Math.sin(a)}" x2="${100+80*Math.cos(a)}" y2="${100+80*Math.sin(a)}" stroke="${i<Math.round(value/100*40)?color:'#d4d4d8'}" stroke-width="2.5" stroke-linecap="round"/>`}).join('')}</g><text x="100" y="101" text-anchor="middle" fill="#292c2d" font-family="Inter, sans-serif" font-size="23" font-weight="600">${value}%</text></svg>`}
function landing(){let r=target();let petals=Array.from({length:8},(_,i)=>`<circle cx="${16+10*Math.cos(i*Math.PI/4)}" cy="${16+10*Math.sin(i*Math.PI/4)}" r="3.5"/>`).join('');return `<section class="landing" aria-label="CareerBridge introduction"><video class="landing-video" autoplay loop muted playsinline preload="auto" disableremoteplayback webkit-playsinline="true" x5-playsinline="true" poster="https://images.unsplash.com/photo-1557683316-973673baf926?w=1600&q=60"><source src="https://d8j0ntlcm91z4.cloudfront.net/user_38xzZboKViGWJOttwIXH07lWA1P/hf_20260424_064411_9e9d7f84-9277-41f4-ab10-59172d89e6be.mp4" type="video/mp4"></video><div class="video-wash"></div><div class="landing-content"><div class="pill-wrap"><div class="landing-nav"><a href="#home" class="flower" aria-label="CareerBridge home"><svg viewBox="0 0 32 32" aria-hidden="true">${petals}<circle cx="16" cy="16" r="3.5"/></svg></a><div class="landing-links"><a href="#home" aria-current="page">Home</a><button class="nav-scroll" data-scroll="platform">Platform</button><button class="nav-scroll" data-scroll="how-it-works">How it works</button><a href="#dashboard">Workspace ↗</a></div><button class="access" data-page="profile"><span>Build <span class="desktop-word">your </span>profile</span><span class="circle-arrow" aria-hidden="true">›</span></button><button class="menu-button" id="landing-menu-toggle" aria-label="Toggle navigation" aria-expanded="false" aria-controls="landing-menu">☰</button><div id="landing-menu" class="landing-menu" hidden><button data-scroll="platform">Our platform</button><button data-scroll="how-it-works">How it works</button><button data-scroll="questions">FAQs</button><a href="#dashboard">My workspace</a></div></div></div><div class="landing-intro"><div class="landing-badge"><span class="orange-dot"></span>CareerBridge</div><h1>Shaping <em>Careers</em><br>of tomorrow</h1><p>Your all-in-one platform for the leap from campus to career.</p><button class="landing-cta" data-page="dashboard">Get started <span class="circle-arrow" aria-hidden="true">›</span></button></div><div class="preview-outer"><div class="preview-tray"><div class="preview-top"><strong>Your next chapter, at a glance</strong><span>PERSONAL CAREER WORKSPACE</span></div><div class="preview-grid"><section class="preview-card"><div class="preview-label">Career match <span>Your profile</span></div><div class="preview-number">${r.score}% <small>${r.known.length} / ${r.skills.length} skills</small></div><div class="preview-caption">${r.name} · skill checklist overlap</div><div class="gauge-title" id="preview-gauge-title">Core skills already in your profile</div><div id="preview-gauge">${gauge(r.score)}</div><div class="gauge-labels"><span>Starting point</span><span>Your potential</span></div><div class="preview-tabs"><button class="active" data-preview-tab="skills">Skill match</button><button data-preview-tab="milestones">Milestones</button></div></section><section class="preview-card"><label for="landing-path">Your recommended path</label><select id="landing-path" aria-label="Preview career path" onchange="chosenRole=this.value"><option>${r.name}</option>${roles.filter(x=>x.name!==r.name).map(x=>`<option>${x.name}</option>`).join('')}</select><label for="landing-hours">Learning goal (hours / week)</label><input type="number" min="1" max="40" step="1" id="landing-hours" value="${state.profile.hours}"><label>Your next focus</label><div class="note" style="margin:0 0 16px;font-size:10px;padding:10px">${gaps().length?gaps().join(' · '):'Build a portfolio project'}</div><div class="preview-form-bottom"><button class="mini-save" id="save-pace">Save</button><button class="cancel" id="cancel-pace">Cancel</button><a class="arrow-link" href="#roadmap" aria-label="Open your roadmap">↗</a></div></section><section class="preview-card"><div class="preview-label">Interview practice <span>Your progress</span></div><div class="preview-number">${Object.values(state.answers).filter(x=>x.trim()).length}<small>of 4 answers</small></div><div class="preview-caption">A little practice. A lot more confidence.</div><div class="gauge-title">Your practice session</div>${gauge(Math.round(Object.values(state.answers).filter(x=>x.trim()).length/4*100),'#9ca3af')}<div class="preview-tabs"><button data-page="interview" class="active">Start practicing ↗</button></div></section></div><p class="preview-footnote">Interactive project demo · Rule-based guidance · Save progress with your account</p></div></div></div></section>`}
function landingSections(){const features=[['profile','01','A profile that starts with you','Bring your education, interests and existing skills together. Update your profile as you learn, and see your recommendations change.','Build your profile'],['careers','02','Explore where you could go','Compare four career paths using a clear skill checklist. See what fits today and what you can work towards next.','Explore career paths'],['roadmap','03','Turn skill gaps into next steps','Identify missing skills and follow a flexible roadmap with learning, project, resume and interview milestones.','Find your roadmap'],['courses','04','Learn with a little more direction','Discover curated learning resources for your skill gaps, from web development and Python to design and communication.','Browse the learning hub'],['resume','05','Tell your story with confidence','Review your resume against a practical checklist, improve your project bullets and download your resume text.','Open resume studio'],['interview','06','Make practice part of the process','Rehearse four interview questions and get structure feedback to make your examples clearer and more specific.','Practice an interview']];return `<div class="landing-below"><div class="scroll-strip"><span>MORE THAN A DESTINATION. A WAY FORWARD.</span><button data-scroll="platform">Discover CareerBridge <span aria-hidden="true">↓</span></button></div><section class="about-section marketing-section" id="platform"><div><div class="marketing-eyebrow">MEET YOUR CAREER COMPANION</div><h2>College gives you a start.<br>Let’s build <em>what’s next.</em></h2></div><div class="about-copy"><p>Choosing a career can feel like connecting pieces without seeing the whole picture. Which role fits your interests? Which skills should you learn? How do you explain what you can do?</p><p>CareerBridge brings those questions into one workspace. Understand your starting point, explore a direction and take practical steps towards your first opportunity.</p><a href="#profile" class="inline-link">Start with your story <span>↗</span></a></div></section><section class="marketing-section feature-section" id="features"><div class="marketing-heading"><div><div class="marketing-eyebrow">WHAT YOU CAN DO HERE</div><h2>A little clarity.<br><em>A lot of possibility.</em></h2></div><p>Tools for every part of your journey,<br>from “where do I start?” to “I’m ready to practice.”</p></div><div class="feature-grid">${features.map(([page,num,title,body,cta])=>`<article class="service-card"><span class="service-number">${num} <span aria-hidden="true">↗</span></span><h3>${title}</h3><p>${body}</p><a href="#${page}">${cta} <span aria-hidden="true">→</span></a></article>`).join('')}</div></section><section class="journey-section marketing-section" id="how-it-works"><div class="marketing-heading"><div><div class="marketing-eyebrow">HOW IT WORKS</div><h2>You bring the ambition.<br>We help with <em>the next step.</em></h2></div><button data-page="profile" class="landing-cta">Build my profile <span class="circle-arrow">›</span></button></div><div class="journey-grid">${[['01','Tell us about you','Add your education, skills, interests and the time you can set aside for learning.'],['02','Find your direction','Compare career paths and understand the skills behind each match.'],['03','Build your momentum','Follow your roadmap, learn something new and put it into a project.'],['04','Prepare to show up','Refine your resume, practice your answers and explore opportunity resources.']].map(([n,t,d])=>`<article><span class="journey-number">${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="marketing-section paths-section"><div class="marketing-heading"><div><div class="marketing-eyebrow">ONE STARTING POINT. DIFFERENT FUTURES.</div><h2>Find a path that<br>feels <em>like you.</em></h2></div><a href="#careers" class="inline-link">Compare all paths ↗</a></div><div class="path-grid">${roles.map((r,i)=>`<a class="path-card path-${i}" href="#careers"><span class="path-symbol" aria-hidden="true">${esc(r.symbol)}</span><div><span class="path-domain">${r.domain}</span><h3>${r.name}</h3><p>${r.desc}</p></div><span class="path-arrow" aria-hidden="true">↗</span></a>`).join('')}</div><p class="section-caption">These four paths are a starting set for exploration. A match is a skill comparison, not a limit on what you can become.</p></section><section class="opportunity-section marketing-section"><div class="opportunity-copy"><div class="marketing-eyebrow">LOOK BEYOND THE CLASSROOM</div><h2>Your next chapter<br>could start <em>anywhere.</em></h2><p>Explore the kinds of internships and entry-level roles you could work towards, or discover public-service and apprenticeship pathways through official Indian portals.</p><div class="opportunity-links"><a href="#jobs">Explore sample opportunities ↗</a><a href="#government">Discover government careers ↗</a></div><small>Opportunity listings in this project are samples. Official portals carry their own current notices and eligibility requirements.</small></div><div class="opportunity-visual"><span class="visual-label">A WORLD OF POSSIBILITIES</span><div class="opportunity-ticket"><span class="ticket-mark">01</span><div><strong>Your first internship</strong><p>Put learning into practice</p></div><span>↗</span></div><div class="opportunity-ticket"><span class="ticket-mark">02</span><div><strong>Your first full-time role</strong><p>Build on what you already know</p></div><span>↗</span></div><div class="opportunity-ticket"><span class="ticket-mark">03</span><div><strong>A future in public service</strong><p>Explore official career portals</p></div><span>↗</span></div><span class="visual-bottom">YOUR JOURNEY DOESN’T HAVE TO LOOK LIKE ANYONE ELSE’S.</span></div></section><section class="faq-section marketing-section" id="questions"><div><div class="marketing-eyebrow">A FEW THINGS TO KNOW</div><h2>Good questions.<br><em>Clear answers.</em></h2><p>Know what to expect before<br>you take your first step.</p></div><div class="faq-list">${[['Who is CareerBridge for?','Students and recent graduates who want a clearer starting point for career exploration, focused learning and interview preparation. You can explore any of the available paths, regardless of your current skill match.'],['How are career matches calculated?','The demo compares the skills you list with each career’s skill checklist. Your interest helps order the results. The displayed percentage is skill overlap, not a prediction of employability or a hiring decision.'],['Is this powered by live AI?','This project currently uses transparent local rules for career matching, resume checks and interview structure feedback. A live AI service is not connected yet.'],['Are the jobs and courses real?','The job cards are clearly marked sample opportunities. Learning resources and government career links lead to external provider or official websites. Check those websites for current availability, costs, certificates and eligibility.'],['Do I need an account, and where is my data saved?','Create an account to save your profile, drafts and progress to the database and access them on another device. You can export or reset your workspace from My profile.'],['Does CareerBridge guarantee a placement?','No. The platform helps you explore and prepare. Hiring outcomes depend on many factors, and learning milestones or skill scores do not guarantee an interview or a job.']].map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="closing-section"><div class="marketing-eyebrow">YOUR FUTURE IS A WORK IN PROGRESS</div><h2>Make your next move<br><em>a little clearer.</em></h2><p>You don’t need every answer today. Just a place to begin.</p><button class="landing-cta" data-page="profile">Start my journey <span class="circle-arrow">›</span></button><span class="closing-note">Free tools · Save your journey with an account</span></section><div class="marketing-footer"><a href="#home" class="footer-brand">CareerBridge<span>.</span></a><p>From campus to your next chapter.</p><div><button data-scroll="platform">About</button><button data-scroll="features">Features</button><button data-scroll="questions">FAQs</button><a href="#dashboard">Workspace ↗</a></div><small>Career readiness project · Rule-based demo</small></div></div>`}

function initLandingMotion(){
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const elements=document.querySelectorAll('.marketing-section > div, .service-card, .journey-grid article, .path-card, .opportunity-ticket, .faq-list details, .closing-section, .marketing-footer');
 if(reduced||!('IntersectionObserver' in window))return;
 window.careerRevealObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');window.careerRevealObserver.unobserve(entry.target)}})},{threshold:0.08,rootMargin:'0px 0px -24px 0px'});
 elements.forEach(el=>{el.classList.add('scroll-reveal');if(el.matches('.service-card,.journey-grid article,.path-card,.opportunity-ticket')){let i=Array.from(el.parentElement.children).indexOf(el);el.style.setProperty('--reveal-delay',Math.min(i%3,2)*70+'ms')}window.careerRevealObserver.observe(el)});
 // Keyboard focus must reveal a control even before its scroll animation runs.
 $('#main').addEventListener('focusin',e=>{let el=e.target.closest('.scroll-reveal');while(el){el.classList.add('is-visible');el=el.parentElement?.closest('.scroll-reveal')}},{passive:true});
}
